PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','reader','admin')),verified INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS codes(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),purpose TEXT NOT NULL,hash TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,kind TEXT NOT NULL,owner TEXT NOT NULL REFERENCES users(id),data TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS records_owner_kind ON records(owner,kind);
CREATE TABLE IF NOT EXISTS slots(id TEXT PRIMARY KEY,reader TEXT NOT NULL REFERENCES users(id),starts TEXT NOT NULL,ends TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),UNIQUE(reader,starts));
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,customer TEXT NOT NULL REFERENCES users(id),reader TEXT NOT NULL REFERENCES users(id),slot TEXT NOT NULL REFERENCES slots(id),status TEXT NOT NULL,format TEXT NOT NULL,intake TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'inr',payment_id TEXT,checkout_url TEXT,idempotency TEXT UNIQUE NOT NULL,created TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS booking_slot_active ON bookings(slot) WHERE status IN ('pending','confirmed','active');
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,booking TEXT NOT NULL REFERENCES bookings(id),sender TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id),mime TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor TEXT,action TEXT NOT NULL,target TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,customer TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL,total INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'inr',address TEXT NOT NULL,lines TEXT NOT NULL,idempotency TEXT NOT NULL UNIQUE,payment_id TEXT,checkout_url TEXT,created TEXT NOT NULL);
